CREATE TABLE tbl(a INTEGER PRIMARY KEY,b INTEGER); CREATE VIEW vw AS SELECT * FROM tbl; CREATE TRIGGER t_del_tbl INSTEAD OF DELETE ON vw FOR EACH ROW BEGIN DELETE FROM tbl WHERE a=OLD.a; END; CREATE TRIGGER t_upd_tbl INSTEAD OF UPDATE ON vw FOR EACH ROW BEGIN UPDATE tbl SET a=NEW.a,b=NEW.b WHERE a=OLD.a; END; CREATE TRIGGER t_ins_tbl INSTEAD OF INSERT ON vw FOR EACH ROW BEGIN INSERT INTO tbl VALUES(NEW.a,NEW.b); END; INSERT INTO tbl VALUES(101,1001);